int vec_expand_(char **data, int *length, int *capacity, int memsz)
{
    int newcap;
    char *newdata;

    if (*length + 1 <= *capacity) {
        return 0;
    }

    newcap = (*capacity == 0) ? 1 : *capacity * 2;
    newdata = (char *)realloc(*data, (size_t)newcap * (size_t)memsz);
    if (newdata == NULL) {
        return -1;
    }

    *data = newdata;
    *capacity = newcap;
    return 0;
}
