int vec_reserve_(char **data, int *length, int *capacity, int memsz, int n)
{
    (void)length;

    if (n <= *capacity)
        return 0;

    if (n < 0 || memsz <= 0)
        return -1;

    if ((size_t)n > ((size_t)-1) / (size_t)memsz)
        return -1;

    {
        char *new_data = (char *)realloc(*data, (size_t)n * (size_t)memsz);
        if (new_data == NULL)
            return -1;

        *data = new_data;
        *capacity = n;
        return 0;
    }
}
