int vec_insert_(char **data, int *length, int *capacity, int memsz, int idx)
{
    int ret = vec_expand_(data, length, capacity, memsz);
    if (ret != 0)
        return ret;

    int old_length = *length - 1;

    memmove(*data + (size_t)(idx + 1) * (size_t)memsz,
            *data + (size_t)idx * (size_t)memsz,
            (size_t)(old_length - idx) * (size_t)memsz);

    return 0;
}
