static int case_insensitive_strcmp(const unsigned char *string1, const unsigned char *string2)
{
    int c1;
    int c2;

    if (string1 == NULL || string2 == NULL)
        return 1;
    if (string1 == string2)
        return 0;

    while (*string1 != '\0' && *string2 != '\0') {
        c1 = tolower((int)*string1);
        c2 = tolower((int)*string2);
        if (c1 != c2)
            return c1 - c2;
        string1++;
        string2++;
    }

    c1 = tolower((int)*string1);
    c2 = tolower((int)*string2);
    return c1 - c2;
}
