CJSON_PUBLIC(char*) cJSON_SetValuestring(cJSON *object, const char *valuestring)
{
    char *copy = NULL;
    size_t old_length;
    size_t new_length;
    size_t source_start;
    size_t dest_start;
    size_t source_end;
    size_t dest_end;

    if ((object == NULL) || ((object->type & cJSON_String) == 0) || ((object->type & cJSON_IsReference) != 0))
    {
        return NULL;
    }

    if ((object->valuestring == NULL) || (valuestring == NULL))
    {
        return NULL;
    }

    old_length = strlen(object->valuestring);
    new_length = strlen(valuestring);

    if (new_length <= old_length)
    {
        source_start = (size_t)valuestring;
        dest_start = (size_t)object->valuestring;
        source_end = source_start + new_length + 1;
        dest_end = dest_start + old_length + 1;

        if ((source_start < dest_end) && (dest_start < source_end))
        {
            return NULL;
        }

        strcpy(object->valuestring, valuestring);
        return object->valuestring;
    }

    copy = (char*)cJSON_strdup((const unsigned char*)valuestring, &global_hooks);
    if (copy == NULL)
    {
        return NULL;
    }

    cJSON_free(object->valuestring);
    object->valuestring = copy;

    return copy;
}
