static unsigned parse_hex4(const unsigned char * const input)
{
    unsigned result = 0;
    int i;

    for (i = 0; i < 4; i++) {
        unsigned char c = input[i];
        unsigned digit;

        if (c >= '0' && c <= '9') {
            digit = (unsigned)(c - '0');
        } else if (c >= 'A' && c <= 'F') {
            digit = (unsigned)(c - 'A' + 10);
        } else if (c >= 'a' && c <= 'f') {
            digit = (unsigned)(c - 'a' + 10);
        } else {
            return 0;
        }

        result = (result << 4) | digit;
    }

    return result;
}
