static unsigned char utf16_literal_to_utf8(const unsigned char * const input_pointer, const unsigned char * const input_end, unsigned char **output_pointer)
{
    unsigned int first_code = 0;
    unsigned int second_code = 0;
    unsigned long codepoint = 0;
    unsigned char sequence_length = 0;
    unsigned char utf8_length = 0;
    unsigned char utf8_position = 0;
    unsigned char first_byte_mark = 0;
    size_t i = 0;
    ptrdiff_t remaining = 0;

    remaining = input_end - input_pointer;
    if (remaining < 6)
    {
        return 0;
    }

    if ((input_pointer[0] != '\\') || (input_pointer[1] != 'u'))
    {
        return 0;
    }

    for (i = 2; i < 6; i++)
    {
        if (!(((input_pointer[i] >= '0') && (input_pointer[i] <= '9')) ||
              ((input_pointer[i] >= 'A') && (input_pointer[i] <= 'F')) ||
              ((input_pointer[i] >= 'a') && (input_pointer[i] <= 'f'))))
        {
            return 0;
        }
    }

    first_code = parse_hex4(input_pointer + 2);

    if ((first_code >= 0xDC00) && (first_code <= 0xDFFF))
    {
        return 0;
    }

    if ((first_code >= 0xD800) && (first_code <= 0xDBFF))
    {
        if (remaining < 12)
        {
            return 0;
        }

        if ((input_pointer[6] != '\\') || (input_pointer[7] != 'u'))
        {
            return 0;
        }

        for (i = 8; i < 12; i++)
        {
            if (!(((input_pointer[i] >= '0') && (input_pointer[i] <= '9')) ||
                  ((input_pointer[i] >= 'A') && (input_pointer[i] <= 'F')) ||
                  ((input_pointer[i] >= 'a') && (input_pointer[i] <= 'f'))))
            {
                return 0;
            }
        }

        second_code = parse_hex4(input_pointer + 8);

        if ((second_code < 0xDC00) || (second_code > 0xDFFF))
        {
            return 0;
        }

        codepoint = 0x10000UL + ((unsigned long)(first_code - 0xD800) << 10) + (unsigned long)(second_code - 0xDC00);
        sequence_length = 12;
    }
    else
    {
        codepoint = (unsigned long)first_code;
        sequence_length = 6;
    }

    if (codepoint < 0x80UL)
    {
        utf8_length = 1;
    }
    else if (codepoint < 0x800UL)
    {
        utf8_length = 2;
        first_byte_mark = 0xC0;
    }
    else if (codepoint < 0x10000UL)
    {
        utf8_length = 3;
        first_byte_mark = 0xE0;
    }
    else
    {
        utf8_length = 4;
        first_byte_mark = 0xF0;
    }

    for (utf8_position = (unsigned char)(utf8_length - 1); utf8_position > 0; utf8_position--)
    {
        (*output_pointer)[utf8_position] = (unsigned char)((codepoint | 0x80UL) & 0xBFUL);
        codepoint >>= 6;
    }

    if (utf8_length > 1)
    {
        (*output_pointer)[0] = (unsigned char)((codepoint | first_byte_mark) & 0xFFUL);
    }
    else
    {
        (*output_pointer)[0] = (unsigned char)(codepoint & 0x7FUL);
    }

    *output_pointer += utf8_length;

    return sequence_length;
}
