static parse_buffer *skip_utf8_bom(parse_buffer * const buffer)
{
    if ((buffer == NULL) || (buffer->content == NULL) || (buffer->offset != 0))
    {
        return NULL;
    }

    if (can_access_at_index(buffer, 3) &&
        (buffer->content[buffer->offset] == 0xEF) &&
        (buffer->content[buffer->offset + 1] == 0xBB) &&
        (buffer->content[buffer->offset + 2] == 0xBF))
    {
        buffer->offset += 3;
    }

    return buffer;
}
