static void skip_multiline_comment(char **input)
{
    char *p;

    p = *input + 2;

    while (*p != '\0') {
        if (*p == '*' && *(p + 1) == '/') {
            p += 2;
            break;
        }
        ++p;
    }

    *input = p;
}
