static void minify_string(char **input, char **output)
{
    char *in = *input;
    char *out = *output;

    *out++ = *in++;

    while (*in != '\0')
    {
        if (*in == '"')
        {
            *out++ = *in++;
            break;
        }
        else if (*in == '\\' && *(in + 1) == '"')
        {
            in++;
            *out++ = *in++;
        }
        else
        {
            *out++ = *in++;
        }
    }

    *input = in;
    *output = out;
}
