static cJSON_bool compare_pointers(const unsigned char *name, const unsigned char *pointer, const cJSON_bool case_sensitive)
{
    if ((name == NULL) || (pointer == NULL))
    {
        return false;
    }

    for (; (*name != '\0') && (*pointer != '\0') && (*pointer != '/'); name++, pointer++)
    {
        if (*pointer == '~')
        {
            pointer++;
            if (*pointer == '0')
            {
                if (*name != '~')
                {
                    return false;
                }
            }
            else if (*pointer == '1')
            {
                if (*name != '/')
                {
                    return false;
                }
            }
            else
            {
                return false;
            }
        }
        else if (case_sensitive)
        {
            if (*name != *pointer)
            {
                return false;
            }
        }
        else
        {
            if (tolower(*name) != tolower(*pointer))
            {
                return false;
            }
        }
    }

    if ((*name != '\0') || ((*pointer != '\0') && (*pointer != '/')))
    {
        return false;
    }

    return true;
}
