CJSON_PUBLIC(char *) cJSONUtils_FindPointerFromObjectTo(const cJSON * const object, const cJSON * const target)
{
    cJSON *current_child = NULL;
    size_t child_index = 0;

    if ((object == NULL) || (target == NULL))
    {
        return NULL;
    }

    if (object == target)
    {
        char *copy = (char*)cJSON_malloc(1);
        if (copy != NULL)
        {
            copy[0] = '\0';
        }
        return copy;
    }

    current_child = object->child;
    while (current_child != NULL)
    {
        char *target_pointer = cJSONUtils_FindPointerFromObjectTo(current_child, target);
        if (target_pointer != NULL)
        {
            if (cJSON_IsArray(object))
            {
                char index_buffer[32];
                char *array_pointer = NULL;
                size_t length = 0;

                sprintf(index_buffer, "/%lu", (unsigned long)child_index);
                length = strlen(index_buffer) + strlen(target_pointer) + 1;
                array_pointer = (char*)cJSON_malloc(length);
                if (array_pointer != NULL)
                {
                    strcpy(array_pointer, index_buffer);
                    strcat(array_pointer, target_pointer);
                }
                cJSON_free(target_pointer);
                return array_pointer;
            }
            else if (cJSON_IsObject(object))
            {
                char *encoded_path = NULL;
                size_t encoded_length = 0;
                size_t length = 0;

                if (current_child->string == NULL)
                {
                    cJSON_free(target_pointer);
                    return NULL;
                }

                encoded_length = pointer_encoded_length((const unsigned char*)current_child->string);
                length = encoded_length + strlen(target_pointer) + 2;
                encoded_path = (char*)cJSON_malloc(length);
                if (encoded_path != NULL)
                {
                    encoded_path[0] = '/';
                    encode_string_as_pointer((unsigned char*)encoded_path + 1, (const unsigned char*)current_child->string);
                    strcat(encoded_path, target_pointer);
                }
                cJSON_free(target_pointer);
                return encoded_path;
            }
            else
            {
                cJSON_free(target_pointer);
                return NULL;
            }
        }

        current_child = current_child->next;
        child_index++;
    }

    return NULL;
}
