static cJSON_bool decode_array_index_from_pointer(const unsigned char * const pointer, size_t * const index)
{
    const unsigned char *p = pointer;
    size_t parsed_index = 0;

    if (*p == '\0')
    {
        return 0;
    }

    if (*p == '0')
    {
        if (p[1] != '\0')
        {
            return 0;
        }

        *index = 0;
        return 1;
    }

    if ((*p < '0') || (*p > '9'))
    {
        return 0;
    }

    while ((*p >= '0') && (*p <= '9'))
    {
        parsed_index = (parsed_index * 10) + (size_t)(*p - '0');
        p++;
    }

    if ((*p != '\0') && (*p != '/'))
    {
        return 0;
    }

    *index = parsed_index;
    return 1;
}
