static int jsmn_parse_string(jsmn_parser *parser, const char *js, const size_t len, jsmntok_t *tokens, const size_t num_tokens)
{
    jsmntok_t *token;
    int start = (int)parser->pos;
    int i;

    parser->pos++;

    for (; parser->pos < len && js[parser->pos] != '\0'; parser->pos++) {
        char c = js[parser->pos];

        if (c == '\"') {
            if (tokens == NULL) {
                return 0;
            }

            token = jsmn_alloc_token(parser, tokens, num_tokens);
            if (token == NULL) {
                parser->pos = (unsigned int)start;
                return JSMN_ERROR_NOMEM;
            }

            jsmn_fill_token(token, JSMN_STRING, start + 1, (int)parser->pos);
#ifdef JSMN_PARENT_LINKS
            token->parent = parser->toksuper;
#endif
            return 0;
        }

        if (c == '\\' && (size_t)parser->pos + 1 < len) {
            parser->pos++;

            switch (js[parser->pos]) {
                case '\"':
                case '/':
                case '\\':
                case 'b':
                case 'f':
                case 'r':
                case 'n':
                case 't':
                    break;

                case 'u':
                    for (i = 0; i < 4; i++) {
                        parser->pos++;

                        if (parser->pos >= len || js[parser->pos] == '\0') {
                            parser->pos = (unsigned int)start;
                            return JSMN_ERROR_PART;
                        }

                        if (!((js[parser->pos] >= '0' && js[parser->pos] <= '9') ||
                              (js[parser->pos] >= 'a' && js[parser->pos] <= 'f') ||
                              (js[parser->pos] >= 'A' && js[parser->pos] <= 'F'))) {
                            parser->pos = (unsigned int)start;
                            return JSMN_ERROR_INVAL;
                        }
                    }
                    break;

                default:
                    parser->pos = (unsigned int)start;
                    return JSMN_ERROR_INVAL;
            }
        }
    }

    parser->pos = (unsigned int)start;
    return JSMN_ERROR_PART;
}
