```c
static void mpc_input_unmark(mpc_input_t *i) {
  int new_slots;
  int j;

  if (i->marks_num < 1) { return; }

  i->marks_num--;

  if (i->marks_slots > (i->marks_num * 3) / 2 &&
      i->marks_slots > MPC_INPUT_MARKS_MIN) {
    new_slots = i->marks_num > MPC_INPUT_MARKS_MIN ? i->marks_num : MPC_INPUT_MARKS_MIN;
    i->marks = realloc(i->marks, sizeof(mpc_state_t) * new_slots);
    i->lasts = realloc(i->lasts, sizeof(char) * new_slots);
    i->marks_slots = new_slots;
  }

  if (i->type == MPC_INPUT_PIPE && i->marks_num == 0) {
    if (i->buffer) {
      for (j = (int)strlen(i->buffer) - 1; j >= 0; j--) {
        ungetc(i->buffer[j], i->file);
      }
    }
    free(i->buffer);
    i->buffer = NULL;
  }
}
