```c
static mpc_err_t *mpc_err_or(mpc_input_t *i, mpc_err_t** x, int n) {
  int j, k, m;
  mpc_err_t *e;
  mpc_state_t state;

  j = -1;
  for (k = 0; k < n; k++) {
    if (x[k] != NULL) { j = k; }
  }

  if (j == -1) { return NULL; }

  e = mpc_malloc(i, sizeof(mpc_err_t));
  e->state = mpc_state_invalid();
  e->expected_num = 0;
  e->expected = NULL;
  e->failure = NULL;
  e->received = '\0';
  e->filename = mpc_malloc(i, strlen(x[j]->filename) + 1);
  strcpy(e->filename, x[j]->filename);

  state = mpc_state_invalid();
  for (k = 0; k < n; k++) {
    if (x[k] == NULL) { continue; }
    if (x[k]->state.pos > state.pos) { state = x[k]->state; }
  }
  e->state = state;

  for (k = 0; k < n; k++) {
    if (x[k] == NULL) { continue; }
    if (x[k]->state.pos != state.pos) { continue; }
    if (x[k]->failure != NULL) {
      e->failure = mpc_malloc(i, strlen(x[k]->failure) + 1);
      strcpy(e->failure, x[k]->failure);
      break;
    }
  }

  if (e->failure == NULL) {
    for (k = 0; k < n; k++) {
      if (x[k] == NULL) { continue; }
      if (x[k]->state.pos != state.pos) { continue; }
      e->received = x[k]->received;
      for (m = 0; m < x[k]->expected_num; m++) {
        if (!mpc_err_contains_expected(i, e, x[k]->expected[m])) {
          mpc_err_add_expected(i, e, x[k]->expected[m]);
        }
      }
    }
  }

  for (k = 0; k < n; k++) {
    if (x[k] != NULL) { mpc_err_delete_internal(i, x[k]); }
  }

  return e;
}
