static mpc_val_t *mpcf_re_range(mpc_val_t *x) {

  mpc_parser_t *p;
  char *s = x;
  char *o = malloc(strlen(s) + 1);
  char *t = o;
  int comp = 0;

  if (*s == '^') { comp = 1; s++; }
  if (!*s) { free(x); free(o); return mpc_fail("Invalid Regex Range Expression"); }

  while (*s) {

    if (*s == '\\') {
      s++;
      if (mpc_re_range_escape_char(*s)) {
        strcpy(t, mpc_re_range_escape_char(*s));
        t += strlen(mpc_re_range_escape_char(*s));
      } else {
        *t++ = *s;
      }
      s++;
      continue;
    }

    if (*s == '-' && t != o && s[1]) {
      char start = *(t - 1);
      char end = s[1];
      s++;
      while (start < end) { *t++ = ++start; }
      s++;
      continue;
    }

    *t++ = *s++;

  }

  *t = '\0';

  p = comp ? mpc_noneof(o) : mpc_oneof(o);
  free(o);
  free(x);

  return p;

}
