static mpc_val_t *mpcaf_grammar_char(mpc_val_t *x, void *s)
{
  mpca_grammar_st_t *st = (mpca_grammar_st_t*)s;
  mpc_parser_t *p;
  char *xs = (char*)mpcf_unescape(x);

  if (xs == NULL) {
    return NULL;
  }

  p = mpc_char(xs[0]);
  free(xs);

  if (p == NULL) {
    return NULL;
  }

  if (!(st->flags & MPCA_LANG_WHITESPACE_SENSITIVE)) {
    p = mpc_tok(p);
    if (p == NULL) {
      return NULL;
    }
  }

  p = mpc_apply(p, mpcf_str_ast);
  if (p == NULL) {
    return NULL;
  }

  p = mpca_tag(p, "char");
  if (p == NULL) {
