static mpc_parser_t *mpca_grammar_find_parser(char *x, mpca_grammar_st_t *st)
{
  int i;
  mpc_parser_t *p;

  if (is_number(x)) {
    int n = atoi(x);

    while (st->parsers_num <= n) {
      p = va_arg(*st->va, mpc_parser_t*);
      if (p == NULL) {
        return mpc_failf("Parser %i requested but only %i parsers supplied.", n, st->parsers_num);
      }

      st->parsers_num++;
      st->parsers = realloc(st->parsers, sizeof(mpc_parser_t*) * (st->parsers_num + 1));
      st->parsers[st->parsers_num - 1] = p;
      st->parsers[st->parsers_num] = NULL;
    }

    return st->parsers[n];
  }

  for (i = 0; i < st->parsers_num; i++) {
    p = st->parsers[i];
    if (p == NULL) {
      return mpc_failf("Unknown parser: %s", x);
    }
    if (p->name != NULL && strcmp(p->name, x) == 0) {
      return p;
    }
  }

  while (1) {
    p = va_arg(*st->va, mpc_parser_t*);
    if (p == NULL || p->name == NULL) {
      return mpc_failf("Unknown parser: %s", x);
    }

    st->parsers_num++;
    st->parsers = realloc(st->parsers, sizeof(mpc_parser_t*) * (st->parsers_num + 1));
    st->parsers[st->parsers_num - 1] = p;
    st->parsers[st->parsers_num] = NULL;

    if (strcmp(p->name, x) == 0) {
      return p;
    }
  }
}
