static parson_bool_t is_valid_utf8(const char *string, size_t string_len)
{
    size_t offset;
    int seq_len;
    JSON_Status status;

    offset = 0;
    while (offset < string_len) {
        seq_len = 0;
        status = verify_utf8_sequence((const unsigned char *)string + offset,
                                      string_len - offset,
                                      &seq_len);
        if (status != JSONSuccess) {
            return PARSON_FALSE;
        }
        if (seq_len <= 0 || (size_t)seq_len > string_len - offset) {
            return PARSON_FALSE;
        }
        offset += (size_t)seq_len;
    }

    return PARSON_TRUE;
}
