static JSON_Status json_object_init(JSON_Object *object, size_t capacity)
{
    size_t i;

    object->wrapping_value = NULL;
    object->cells = NULL;
    object->hashes = NULL;
    object->names = NULL;
    object->values = NULL;
    object->cell_ixs = NULL;
    object->count = 0;
    object->item_capacity = 0;
    object->cell_capacity = capacity;

    if (capacity == 0) {
        return JSONSuccess;
    }

    object->item_capacity = (capacity / 10) * 7 + ((capacity % 10) * 7) / 10;

    object->cells = (size_t *)parson_malloc(object->cell_capacity * sizeof(size_t));
    object->names = (char **)parson_malloc(object->item_capacity * sizeof(char *));
    object->values = (JSON_Value **)parson_malloc(object->item_capacity * sizeof(JSON_Value *));
    object->cell_ixs = (size_t *)parson_malloc(object->item_capacity * sizeof(size_t));
    object->hashes = (unsigned long *)parson_malloc(object->item_capacity * sizeof(unsigned long));

    if (object->cells == NULL || object->names == NULL || object->values == NULL ||
        object->cell_ixs == NULL || object->hashes == NULL) {
        parson_free(object->cells);
        parson_free(object->names);
        parson_free(object->values);
        parson_free(object->cell_ixs);
        parson_free(object->hashes);

        object->cells = NULL;
        object->names = NULL;
        object->values = NULL;
        object->cell_ixs = NULL;
        object->hashes = NULL;
        object->count = 0;

        return JSONFailure;
    }

    for (i = 0; i < capacity; i++) {
        object->cells[i] = OBJECT_INVALID_IX;
    }

    return JSONSuccess;
}
