    size_t cell_ix = (size_t)hash & (cell_capacity - 1);
    size_t i;

    *out_found = PARSON_FALSE;

    for (i = 0; i < cell_capacity; i++) {
        size_t item_ix;
        const char *stored_key;

        if (object->cells[cell_ix] == OBJECT_INVALID_IX) {
            return cell_ix;
        }

        if (object->hashes[cell_ix] == hash) {
            item_ix = object->cells[cell_ix];
            stored_key = object->names[item_ix];

            if (strlen(stored_key) == key_len &&
                memcmp(stored_key, key, key_len) == 0) {
                *out_found = PARSON_TRUE;
                return cell_ix;
            }
        }

        cell_ix = (cell_ix + 1) & (cell_capacity - 1);
    }

    return OBJECT_INVALID_IX;
}
