static JSON_Status json_object_add(JSON_Object *object, char *name, JSON_Value *value)
{
    unsigned long hash;
    size_t key_len;
    size_t cell_ix;
    parson_bool_t found;
    JSON_Status status;

    if (object == NULL || name == NULL || value == NULL) {
        return JSONFailure;
    }

    key_len = strlen(name);
    hash = hash_string(name, key_len);
    found = PARSON_FALSE;
    cell_ix = json_object_get_cell_ix(object, name, key_len, hash, &found);
    if (found) {
        return JSONFailure;
    }

    if (object->count >= object->item_capacity) {
        status = json_object_grow_and_rehash(object);
        if (status != JSONSuccess) {
            return JSONFailure;
        }
        cell_ix = json_object_get_cell_ix(object, name, key_len, hash, &found);
    }

    object->names[object->count] = name;
    object->values[object->count] = value;
    object->cell_ixs[object->count] = cell_ix;
    object->hashes[object->count] = hash;
    object->cells[cell_ix] = object->count;
    value->parent = json_object_get_wrapping_value(object);
    object->count++;

    return JSONSuccess;
}
