static JSON_Status json_array_resize(JSON_Array *array, size_t new_capacity)
{
    JSON_Value **new_items;
    size_t alloc_capacity;
    size_t item_size;

    if (new_capacity == 0) {
        return JSONFailure;
    }

    alloc_capacity = new_capacity;
    if (array->count > alloc_capacity) {
        alloc_capacity = array->count;
    }

    item_size = sizeof(JSON_Value *);
    if (alloc_capacity > ((size_t)-1) / item_size) {
        return JSONFailure;
    }

    new_items = (JSON_Value **)parson_malloc(alloc_capacity * item_size);
    if (new_items == NULL) {
        return JSONFailure;
    }

    if (array->items != NULL && array->count > 0) {
        memcpy(new_items, array->items, array->count * item_size);
    }

    if (array->items != NULL) {
        parson_free(array->items);
    }

    array->items = new_items;
    array->capacity = new_capacity;
    return JSONSuccess;
}
