```c
static JSON_Status skip_quotes(const char **string)
{
    const char *cursor = *string;

    if (*cursor != '"') {
        return JSONFailure;
    }

    cursor++;

    while (*cursor != '\0') {
        if (*cursor == '\\') {
            cursor++;
            if (*cursor == '\0') {
                *string = cursor;
                return JSONFailure;
            }
            cursor++;
        } else if (*cursor == '"') {
            cursor++;
            *string = cursor;
            return JSONSuccess;
        } else {
            cursor++;
        }
    }

    *string = cursor;
    return JSONFailure;
}
```

