    size_t processed_len;

    opening_quote = *string;
    start = opening_quote + 1;

    if (skip_quotes(string) != JSONSuccess) {
        return NULL;
    }

    input_len = (size_t)((*string - 1) - start);

    result = process_string(start, input_len, &processed_len);
    if (result == NULL) {
