```c
static JSON_Value * parse_array_value(const char **string, size_t nesting)
{
    JSON_Value *output_value;
    JSON_Array *output_array;

    output_value = json_value_init_array();
    if (output_value == NULL) {
        return NULL;
    }
    output_array = json_value_get_array(output_value);
    if (output_array == NULL) {
        json_value_free(output_value);
        return NULL;
    }
    if (**string != '[') {
        json_value_free(output_value);
        return NULL;
    }
    SKIP_CHAR(string);
    SKIP_WHITESPACES(string);
    if (**string == ']') {
        SKIP_CHAR(string);
        return output_value;
    }
    while (**string != '\0') {
        JSON_Value *new_value = parse_value(string, nesting + 1);
        if (new_value == NULL) {
            json_value_free(output_value);
            return NULL;
        }
        if (json_array_add(output_array, new_value) != JSONSuccess) {
            json_value_free(new_value);
            json_value_free(output_value);
            return NULL;
        }
        SKIP_WHITESPACES(string);
        if (**string != ',') {
            break;
        }
        SKIP_CHAR(string);
        SKIP_WHITESPACES(string);
        if (**string == ']') {
            break;
        }
    }
    SKIP_WHITESPACES(string);
    if (**string != ']' || json_array_resize(output_array, json_array_get_count(output_array)) != JSONSuccess) {
        json_value_free(output_value);
        return NULL;
    }
    SKIP_CHAR(string);
    return output_value;
}
