```c
JSON_Value * json_value_deep_copy(const JSON_Value *value)
{
    JSON_Value_Type type;
    JSON_Value *new_value;
    JSON_Value *temp_value;
    JSON_Value *copied_value;
    JSON_Array *src_array;
    JSON_Array *new_array;
    JSON_Object *src_object;
    JSON_Object *new_object;
    const JSON_String *string_desc;
    char *string_copy;
    char *name_copy;
    const char *name;
    size_t count;
    size_t i;

    if (value == NULL) {
        return NULL;
    }

    type = json_value_get_type(value);

    switch (type) {
        case JSONNull:
            return json_value_init_null();

        case JSONBoolean:
            return json_value_init_boolean(json_value_get_boolean(value));

        case JSONNumber:
            return json_value_init_number(json_value_get_number(value));

        case JSONString:
            string_desc = json_value_get_string_desc(value);
            if (string_desc == NULL || string_desc->chars == NULL) {
                return NULL;
            }
            string_copy = parson_strndup(string_desc->chars, string_desc->length);
            if (string_copy == NULL) {
                return NULL;
            }
            new_value = json_value_init_string_no_copy(string_copy, string_desc->length);
            if (new_value == NULL) {
                parson_free(string_copy);
                return NULL;
            }
            return new_value;

        case JSONArray:
            src_array = json_value_get_array(value);
            if (src_array == NULL) {
                return NULL;
            }
            new_value = json_value_init_array();
            if (new_value == NULL) {
                return NULL;
            }
            new_array = json_value_get_array(new_value);
            if (new_array == NULL) {
                json_value_free(new_value);
                return NULL;
            }
            count = json_array_get_count(src_array);
            for (i = 0; i < count; i++) {
                temp_value = json_array_get_value(src_array, i);
                if (temp_value == NULL) {
                    json_value_free(new_value);
                    return NULL;
                }
                copied_value = json_value_deep_copy(temp_value);
                if (copied_value == NULL) {
                    json_value_free(new_value);
                    return NULL;
                }
                if (json_array_add(new_array, copied_value) != JSONSuccess) {
                    json_value_free(copied_value);
                    json_value_free(new_value);
                    return NULL;
                }
            }
            return new_value;

        case JSONObject:
            src_object = json_value_get_object(value);
            if (src_object == NULL) {
                return NULL;
            }
            new_value = json_value_init_object();
            if (new_value == NULL) {
                return NULL;
            }
            new_object = json_value_get_object(new_value);
            if (new_object == NULL) {
                json_value_free(new_value);
                return NULL;
            }
            count = json_object_get_count(src_object);
            for (i = 0; i < count; i++) {
                name = json_object_get_name(src_object, i);
                if (name == NULL) {
                    json_value_free(new_value);
                    return NULL;
                }
                temp_value = json_object_get_value(src_object, name);
                if (temp_value == NULL) {
                    json_value_free(new_value);
                    return NULL;
                }
                copied_value = json_value_deep_copy(temp_value);
                if (copied_value == NULL) {
                    json_value_free(new_value);
                    return NULL;
                }
                name_copy = parson_strdup(name);
                if (name_copy == NULL) {
                    json_value_free(copied_value);
                    json_value_free(new_value);
                    return NULL;
                }
                if (json_object_add(new_object, name_copy, copied_value) != JSONSuccess) {
                    parson_free(name_copy);
                    json_value_free(copied_value);
                    json_value_free(new_value);
                    return NULL;
                }
            }
            return new_value;

        default:
            return NULL;
    }
}
```

