JSON_Status json_object_set_value(JSON_Object *object, const char *name, JSON_Value *value)
{
    unsigned long hash;
    size_t name_len;
    size_t i;
    size_t item_ix;
    parson_bool_t found;
    char *new_name;
    JSON_Value *old_value;

    if (object == NULL || name == NULL || value == NULL || value->parent != NULL) {
        return JSONFailure;
    }

    name_len = strlen(name);
    hash = hash_string(name, name_len);
    found = PARSON_FALSE;
    i = json_object_get_cell_ix(object, name, name_len, hash, &found);

    if (found) {
        item_ix = object->cells[i];
        old_value = object->values[item_ix];
        json_value_free(old_value);
        object->values[item_ix] = value;
        value->parent = json_object_get_wrapping_value(object);
        return JSONSuccess;
    }

    if (object->count >= object->item_capacity) {
        if (json_object_grow_and_rehash(object) == JSONFailure) {
            return JSONFailure;
        }
        found = PARSON_FALSE;
        i = json_object_get_cell_ix(object, name, name_len, hash, &found);
    }

    new_name = parson_strdup(name);
    if (new_name == NULL) {
        return JSONFailure;
    }

    item_ix = object->count;
    object->names[item_ix] = new_name;
    object->values[item_ix] = value;
    object->hashes[item_ix] = hash;
    object->cells[i] = item_ix;
    object->cell_ixs[item_ix] = i;
    object->count++;
    value->parent = json_object_get_wrapping_value(object);

    return JSONSuccess;
}
