static double fac(double a)
{
    if (!(a >= 0.0)) {
        return NAN;
    }

    if (a > (double)UINT_MAX) {
        return INFINITY;
    }

    unsigned int n = (unsigned int)a;
    unsigned long long result = 1;
    unsigned int i;

    for (i = 2; i <= n; ++i) {
        if (result > ULLONG_MAX / (unsigned long long)i) {
            return INFINITY;
        }
        result *= (unsigned long long)i;
    }

    return (double)result;
}
