static double ncr(double n, double r)
{
    unsigned long long int n64, k, result, i;
    double max32 = (double)UINT_MAX;

    if (!(n >= 0.0) || !(r >= 0.0))
        return NAN;
    if (n < r)
        return NAN;
    if (n > max32 || r > max32)
        return HUGE_VAL;

    n64 = (unsigned long long int)n;
    k = (unsigned long long int)r;

    if (k > n64 / 2ULL)
        k = n64 - k;

    result = 1ULL;

    for (i = 1ULL; i <= k; ++i) {
        unsigned long long int num = n64 - k + i;
        unsigned long long int den = i;
        unsigned long long int g;

        g = gcd(num, den);
        num /= g;
        den /= g;

        g = gcd(result, den);
        result /= g;
        den /= g;

        if (result > ULLONG_MAX / num)
            return HUGE_VAL;

        result *= num;
    }

    return (double)result;
}
