static double parse_number(state *s)
{
    const char *p = s->next;
    double value = 0.0;
    int c;
    int digits;

    c = (unsigned char)p[0];
    if (c == '0' && (p[1] == 'x' || p[1] == 'X')) {
        int c2 = (unsigned char)p[2];
        if ((c2 >= '0' && c2 <= '9') ||
            (c2 >= 'a' && c2 <= 'f') ||
            (c2 >= 'A' && c2 <= 'F')) {
            p += 2;
            c = (unsigned char)p[0];
            while ((c >= '0' && c <= '9') ||
                   (c >= 'a' && c <= 'f') ||
                   (c >= 'A' && c <= 'F')) {
                int d;
                if (c >= '0' && c <= '9') {
                    d = c - '0';
                } else if (c >= 'a' && c <= 'f') {
                    d = c - 'a' + 10;
                } else {
                    d = c - 'A' + 10;
                }
                value = value * 16.0 + (double)d;
                p++;
                c = (unsigned char)p[0];
            }
            s->next = p;
            s->type = TOK_NUMBER;
            return value;
        }
    }

    digits = 0;
    c = (unsigned char)p[0];
    while (c >= '0' && c <= '9') {
        value = value * 10.0 + (double)(c - '0');
        p++;
        digits++;
        c = (unsigned char)p[0];
    }

    if (c == '.') {
        int after = 0;
        double frac = 0.1;
        p++;
        c = (unsigned char)p[0];
        while (c >= '0' && c <= '9') {
            value += frac * (double)(c - '0');
            frac *= 0.1;
            p++;
            after++;
            c = (unsigned char)p[0];
        }
        if (digits == 0 && after == 0) {
            s->type = TOK_ERROR;
            return 0.0;
        }
    } else if (digits == 0) {
        s->type = TOK_ERROR;
        return 0.0;
    }

    c = (unsigned char)p[0];
    if (c == 'e' || c == 'E') {
        const char *q = p + 1;
        int sign = 1;
        int exponent = 0;
        int qc = (unsigned char)q[0];

        if (qc == '+' || qc == '-') {
            sign = (qc == '-') ? -1 : 1;
            q++;
            qc = (unsigned char)q[0];
        }

        if (qc >= '0' && qc <= '9') {
            while (qc >= '0' && qc <= '9') {
                if (exponent < 100000) {
                    exponent = exponent * 10 + (qc - '0');
                }
                q++;
                qc = (unsigned char)q[0];
            }

            if (value != 0.0) {
                if (exponent <= 22) {
                    double p10 = exact_pow10[exponent];
                    value *= (sign > 0) ? p10 : 1.0 / p10;
                } else {
                    value *= pow(10.0, (double)sign * (double)exponent);
                }
            }
            p = q;
        }
    }

    s->next = p;
    s->type = TOK_NUMBER;
    return value;
}
