```c
static void next_token(state *s)
{
    s->type = TOK_NULL;
    s->prec = PREC_NONE;

    do {
        if (!*s->next) {
            s->type = TOK_END;
            return;
        }

        if ((s->next[0] >= '0' && s->next[0] <= '9') || s->next[0] == '.') {
            s->value = parse_number(s);
            s->type = TOK_NUMBER;
        } else {
            if (isalpha((unsigned char)s->next[0])) {
                const char *start;
                start = s->next;
                while (isalpha((unsigned char)s->next[0]) ||
                       isdigit((unsigned char)s->next[0]) ||
                       s->next[0] == '_') {
                    s->next += 1;
                }

                {
                    const te_variable *var;
                    var = find_lookup(s, start, s->next - start);
                    if (!var) {
                        var = find_builtin(start, s->next - start);
                    }

                    if (!var) {
                        s->type = TOK_ERROR;
                    } else {
                        switch (TYPE_MASK(var->type)) {
                            case TE_VARIABLE:
                                s->type = TOK_VARIABLE;
                                s->bound = var->address;
                                break;

                            case TE_CLOSURE0:
                            case TE_CLOSURE1:
                            case TE_CLOSURE2:
                            case TE_CLOSURE3:
                            case TE_CLOSURE4:
                            case TE_CLOSURE5:
                            case TE_CLOSURE6:
                            case TE_CLOSURE7:
                                s->context = var->context;
                                /* fall through */
                            case TE_FUNCTION0:
                            case TE_FUNCTION1:
                            case TE_FUNCTION2:
                            case TE_FUNCTION3:
                            case TE_FUNCTION4:
                            case TE_FUNCTION5:
                            case TE_FUNCTION6:
                            case TE_FUNCTION7:
                                s->type = var->type;
                                s->function = var->address;
                                break;

                            default:
                                s->type = TOK_ERROR;
                                break;
                        }
                    }
                }
            } else {
                switch (s->next++[0]) {
                    case '+':
                        infix(s, add, PREC_SUM);
                        break;
                    case '-':
                        infix(s, sub, PREC_SUM);
                        break;
                    case '*':
                        infix(s, mul, PREC_TERM);
                        break;
                    case '/':
                        infix(s, divide, PREC_TERM);
                        break;
                    case '^':
                        infix(s, pow, PREC_POW);
                        break;
                    case '%':
                        infix(s, fmod, PREC_TERM);
                        break;
                    case '(':
                        s->type = TOK_OPEN;
                        break;
                    case ')':
                        s->type = TOK_CLOSE;
                        break;
                    case ',':
                        s->type = TOK_SEP;
                        s->function = comma;
                        s->prec = PREC_LIST;
                        break;
                    case ' ':
                    case '\t':
                    case '\n':
                    case '\r':
                        break;
                    case '=':
                        if (match(s, '=')) {
                            infix(s, equal, PREC_EQ);
                        } else {
                            s->type = TOK_ERROR;
                        }
                        break;
                    case '>':
                        if (match(s, '=')) {
                            infix(s, greater_eq, PREC_REL);
                        } else {
                            infix(s, greater, PREC_REL);
                        }
                        break;
                    case '<':
                        if (match(s, '=')) {
                            infix(s, lower_eq, PREC_REL);
                        } else {
                            infix(s, lower, PREC_REL);
                        }
                        break;
                    case '&':
                        if (match(s, '&')) {
                            infix(s, logical_and, PREC_AND);
                        } else {
                            s->type = TOK_ERROR;
                        }
                        break;
                    case '|':
                        if (match(s, '|')) {
                            infix(s, logical_or, PREC_OR);
                        } else {
                            s->type = TOK_ERROR;
                        }
                        break;
                    default:
                        s->type = TOK_ERROR;
                        break;
                }
            }
        }
    } while (s->type == TOK_NULL);
}
