```c
static te_expr *base(state *s)
{
    te_expr *ret;
    int arity;

    switch (TYPE_MASK(s->type)) {
    case TOK_NUMBER:
        ret = new_expr(TE_CONSTANT, 0);
        CHECK_NULL(ret);
        ret->value = s->value;
        next_token(s);
        break;

    case TOK_VARIABLE:
        ret = new_expr(TE_VARIABLE, 0);
        CHECK_NULL(ret);
        ret->bound = s->bound;
        next_token(s);
        break;

    case TE_FUNCTION0:
    case TE_CLOSURE0:
        ret = new_expr(s->type, 0);
        CHECK_NULL(ret);
        ret->function = s->function;
        if (IS_CLOSURE(s->type)) ret->parameters[0] = s->context;
        next_token(s);
        if (s->type == TOK_OPEN) {
            next_token(s);
            if (s->type != TOK_CLOSE) {
                s->type = TOK_ERROR;
            } else {
                next_token(s);
            }
        }
        break;

    case TE_FUNCTION1:
    case TE_CLOSURE1:
        ret = new_expr(s->type, 0);
        CHECK_NULL(ret);
        ret->function = s->function;
        if (IS_CLOSURE(s->type)) ret->parameters[1] = s->context;
        next_token(s);
        ret->parameters[0] = power(s);
        CHECK_NULL(ret->parameters[0], te_free(ret));
        break;

    case TE_FUNCTION2: case TE_FUNCTION3: case TE_FUNCTION4:
    case TE_FUNCTION5: case TE_FUNCTION6: case TE_FUNCTION7:
    case TE_CLOSURE2: case TE_CLOSURE3: case TE_CLOSURE4:
    case TE_CLOSURE5: case TE_CLOSURE6: case TE_CLOSURE7:
        arity = ARITY(s->type);
        ret = new_expr(s->type, 0);
        CHECK_NULL(ret);
        ret->function = s->function;
        if (IS_CLOSURE(s->type)) ret->parameters[arity] = s->context;
        next_token(s);
        if (s->type != TOK_OPEN) {
            s->type = TOK_ERROR;
        } else {
            int i;
            next_token(s);
            for (i = 0; i < arity; i++) {
                if (i > 0) {
                    if (s->type != TOK_SEP) {
                        s->type = TOK_ERROR;
                        break;
                    }
                    next_token(s);
                }
                ret->parameters[i] = binary(s, PREC_OR);
                CHECK_NULL(ret->parameters[i], te_free(ret));
            }
            if (s->type != TOK_CLOSE) {
                s->type = TOK_ERROR;
            } else {
                next_token(s);
            }
        }
        break;

    case TOK_OPEN:
        next_token(s);
        ret = binary(s, PREC_LIST);
        CHECK_NULL(ret);
        if (s->type != TOK_CLOSE) {
            s->type = TOK_ERROR;
        } else {
            next_token(s);
        }
        break;

    default:
        ret = new_expr(0, 0);
        CHECK_NULL(ret);
        ret->value = NAN;
        s->type = TOK_ERROR;
        break;
    }

    return ret;
}
