static te_expr *power(state *s)
{
    int sign = 1;
    int logical = 0;
    te_expr *ret;

    while (s->type == TOK_INFIX &&
           (s->function == add || s->function == sub || s->function == logical_not)) {
        if (s->function == sub) {
            if (!logical) {
                sign = -sign;
            }
        } else if (s->function == logical_not) {
            logical = (logical == 1) ? 2 : 1;
        }
        next_token(s);
    }

    if (s->depth == TE_MAX_DEPTH) {
        s->type = TOK_ERROR;
        return 0;
    }

    s->depth++;
    ret = base(s);
    s->depth--;

    if (logical == 0) {
        if (sign == -1) {
            ret = new_fun(TE_FUNCTION1 | TE_FLAG_PURE, negate, ret, 0);
            s->applied_unary = 1;
        } else {
            s->applied_unary = 0;
        }
    } else if (logical == 1) {
        if (sign == -1) {
            ret = new_fun(TE_FUNCTION1 | TE_FLAG_PURE, negate_logical_not, ret, 0);
        } else {
            ret = new_fun(TE_FUNCTION1 | TE_FLAG_PURE, logical_not, ret, 0);
        }
        s->applied_unary = 1;
    } else {
        if (sign == -1) {
            ret = new_fun(TE_FUNCTION1 | TE_FLAG_PURE, negate_logical_notnot, ret, 0);
        } else {
            ret = new_fun(TE_FUNCTION1 | TE_FLAG_PURE, logical_notnot, ret, 0);
        }
        s->applied_unary = 1;
    }

    return ret;
}
