static te_expr *binary(state *s, int prec)
{
    te_expr *lhs = operand(s, prec);
    if (!lhs) {
        return NULL;
    }

    while ((s->type == TOK_INFIX || s->type == TOK_SEP) && s->prec == prec) {
        const void *function = s->function;
        next_token(s);
        te_expr *rhs = operand(s, prec);
        if (!rhs) {
            return NULL;
        }
        lhs = new_fun(TE_FUNCTION2 | TE_FLAG_PURE, function, lhs, rhs);
        if (!lhs) {
            return NULL;
        }
    }

    return lhs;
}
