double te_eval(const te_expr *n) {
    if (!n) return NAN;

    switch (TYPE_MASK(n->type)) {
        case TE_CONSTANT: return n->value;
        case TE_VARIABLE: return *n->bound;

        case TE_FUNCTION0: return TE_FUN(void)();
        case TE_FUNCTION1: return TE_FUN(double)(M(0));
