te_expr *te_compile(const char *expression, const te_variable *variables, int var_count, int *error)
{
    state s;
    te_expr *root;

    s.next = expression;
    s.type = TOK_NULL;
    s.prec = PREC_NONE;
    s.value = 0.0;
    s.context = NULL;
    s.lookup = variables;
    s.lookup_len = var_count;
    s.applied_unary = 0;
    s.depth = 0;

    next_token(&s);
    root = binary(&s, PREC_NONE);

    if (root == NULL || s.type != TOK_END) {
        te_free(root);

        if (error != NULL) {
            if (s.next == expression) {
                *error = -1;
            } else {
                int err = (int)(s.next - expression);
                if (err == 0) {
                    err = 1;
                }
                *error = err;
            }
        }

        return NULL;
    }

    optimize(root);

    if (error != NULL) {
        *error = 0;
    }

    return root;
}
